function connectChat(roomId){disconnectChat();chatRoomId=roomId;if(!roomId){setChatStatus(tr('chatUnavailable'),false);return;}setChatStatus(tr('connecting'),false);try{var socket=new WebSocket(pusherUrl);chatSocket=socket;socket.onmessage=function(event){if(socket!==chatSocket)return;try{var packet=JSON.parse(event.data),payload=typeof packet.data==='string'?JSON.parse(packet.data):packet.data;if(packet.event==='pusher:connection_established')socket.send(JSON.stringify({event:'pusher:subscribe',data:{auth:'',channel:'chatrooms.'+roomId+'.v2'}}));else if(packet.event==='pusher_internal:subscription_succeeded'){chatConnected=true;updateConnectedStatus();}else if(packet.event==='pusher:ping')socket.send(JSON.stringify({event:'pusher:pong',data:{}}));else if(packet.event&&packet.event.indexOf('ChatMessage')>=0)addChatMessage(payload||{});}catch(ignorePacket){}};socket.onerror=function(){if(socket===chatSocket){chatConnected=false;setChatStatus(tr('chatReconnecting'),false);}};socket.onclose=function(){if(socket!==chatSocket||!playing)return;chatSocket=null;chatConnected=false;setChatStatus(tr('restoringConnection'),false);chatReconnect=setTimeout(function(){if(playing)connectChat(roomId);},3000);};}catch(e){chatConnected=false;setChatStatus(tr('chatFailed'),false);chatReconnect=setTimeout(function(){if(playing)connectChat(roomId);},4000);}}
function qualityIndex(id){for(var i=0;i<qualityProfiles.length;i++)if(qualityProfiles[i].id===id)return i;return 0;}
