function renderQualityMenu(){qualityList.innerHTML='';qualityProfiles.forEach(function(profile,index){var row=document.createElement('div'),label=document.createElement('strong'),detail=document.createElement('span');row.className='quality-option'+(profile.id===selectedQuality?' selected':'')+(index===qualityCursor?' focused':'');row.setAttribute('data-selected-label',tr('saved'));label.textContent=qualityLabel(profile);detail.textContent=profile.detail||(profile.detailKey?tr(profile.detailKey):'');row.appendChild(label);row.appendChild(detail);qualityList.appendChild(row);});}
