function revealVideo(){view.classList.remove('player-error','offline-state');view.classList.add('player-ready');if(playbackMode==='vod')view.classList.add('vod-mode');document.documentElement.classList.add('video-playing');document.body.classList.add('video-playing');planeMethodSet=false;applyVideoLayout(false);}
