function updateVodBar(position,fromPlayer){if(playbackMode!=='vod')return;if(fromPlayer&&scrubbing)return;var dur=vodDuration;try{if(window.webapis&&webapis.avplay){var d=webapis.avplay.getDuration();if(d&&d>0)dur=d;vodDuration=dur;if(position===undefined)position=webapis.avplay.getCurrentTime();}}catch(e){}if(!dur)dur=1;position=Number(position)||0;vodFill.style.width=Math.max(0,Math.min(100,(position/dur)*100))+'%';vodTime.textContent=formatClock(position)+' / '+formatClock(dur);}
function vodSkipFromHold(held){var t=Math.max(0,(held-160)/1000);return 10000+Math.pow(t,2.35)*220000;}
function currentVodTime(){try{if(window.webapis&&webapis.avplay)return webapis.avplay.getCurrentTime()||0;}catch(e){}return 0;}
function startScrub(dir){if(playbackMode!=='vod')return;var now=Date.now(),dur=vodDuration||1;if(!scrubbing||scrubDir!==dir){scrubbing=true;scrubDir=dir;scrubStarted=now;scrubBase=currentVodTime();}try{if(window.webapis&&webapis.avplay){var d=webapis.avplay.getDuration();if(d&&d>0)dur=d,vodDuration=d;}}catch(e){}scrubPos=Math.max(0,Math.min(dur,scrubBase+dir*vodSkipFromHold(now-scrubStarted)));updateVodBar(scrubPos,false);showHud();clearTimeout(scrubTimer);scrubTimer=setTimeout(commitScrub,280);}
function commitScrub(){if(!scrubbing)return;var target=Math.floor(scrubPos);scrubbing=false;clearTimeout(scrubTimer);scrubTimer=null;if(!window.webapis||!webapis.avplay)return;try{webapis.avplay.seekTo(target);}catch(e){try{var cur=currentVodTime(),delta=target-cur;if(delta>0)webapis.avplay.jumpForward(delta);else if(delta<0)webapis.avplay.jumpBackward(Math.abs(delta));}catch(e2){}}showHud();setTimeout(function(){updateVodBar(undefined,false);},400);}
