function channelDisplayName(data,fallback){return String((data&&data.user&&data.user.username)||data&&data.username||fallback||'Kick');}
function leavePlayer(ended){cancelScrub();disconnectChat();stopAVPlay();playing=false;releaseScreenSaver();currentStreamUrl=null;document.documentElement.classList.remove('video-playing');document.body.classList.remove('video-playing');view.classList.add('hidden');if(fromPlayerToHub||ended){fromPlayerToHub=false;openHub(currentChannelName,false);}else{home.classList.remove('hidden');focusDefault();}renderHistory();}
