function streamRequestFailed(name,title,detail,polling){if(polling){setStatus(tr('offlineTitle',{name:currentChannelDisplayName||name}),tr('offlineRetry'),false);return;}setStatus(title,detail,true);}
function requestStream(name,polling){var requestId=++streamRequestSeq;xhrGet('https://kick.com/api/v2/channels/'+encodeURIComponent(name),15000,function(data){if(!playing||currentChannelName!==name||requestId!==streamRequestSeq)return;var isLive=!!(data.livestream&&data.livestream.is_live!==false);if(!isLive||!data.playback_url){showOfflineThenHub(name);return;}var roomId=data.chatroom&&data.chatroom.id,userId=data.user_id||(data.user&&data.user.id),keepChat=!!(chatSocket&&chatRoomId===roomId),masterUrl=data.playback_url;clearOfflinePolling();currentChannelDisplayName=channelDisplayName(data,currentChannelDisplayName||name);currentKickUserId=userId;currentRoomId=roomId;view.classList.remove('offline-state','player-error');setStatus(tr('streamStarting',{name:currentChannelDisplayName}),tr('streamStartingDetail'),false);if(!keepChat)loadSevenTV(userId);loadQualityProfiles(masterUrl,function(profiles){if(!playing||requestId!==streamRequestSeq)return;qualityProfiles=profiles;selectedQuality=currentQuality().id;currentStreamUrl=currentQuality().url||masterUrl;updateNowPlaying();startAVPlay(currentStreamUrl,currentRoomId,keepChat);});},function(err){if(playing)streamRequestFailed(name,tr('kickFailed'),String(err),polling);});}
function avErrorText(error){if(error===undefined||error===null)return tr('unknown');if(typeof error==='string')return error;var name=error.name||error.code||'',message=error.message||String(error);return name&&message&&message!==name?name+': '+message:(message||name||tr('unknown'));}
function startAVPlay(url,roomId,keepChat){if(!window.webapis||!webapis.avplay){setStatus(tr('avUnavailable'),tr('avUnavailableDetail'),true);return;}var attemptId=++avPlaySequence;function active(){return playing&&currentStreamUrl===url&&attemptId===avPlaySequence;}function failed(error,title){if(!active())return;setStatus(title,avErrorText(error),true);}try{try{var oldState=webapis.avplay.getState();if(oldState==='PLAYING'||oldState==='PAUSED'||oldState==='READY')webapis.avplay.stop();if(webapis.avplay.getState()!=='NONE')webapis.avplay.close();}catch(ignore){}planeMethodSet=false;applyVideoLayout(false);webapis.avplay.open(url);applyVideoLayout(false);if(playbackMode!=='vod'&&!keepChat)connectChat(roomId);webapis.avplay.setListener({onbufferingstart:function(){if(active())setStatus(tr('loadingVideo'),tr('bufferingDetail'));},onbufferingprogress:function(percent){if(active())document.getElementById('statusDetail').textContent='Buffer '+percent+' %';},onbufferingcomplete:function(){if(active()){revealVideo();scheduleRectHold();showHud();}},oncurrentplaytime:function(time){if(active()&&!view.classList.contains('player-ready'))revealVideo();if(active())updateVodBar(time,true);},onstreamcompleted:function(){if(active())leavePlayer(true);},onerror:function(error){if(active())setStatus(tr('playbackError'),avErrorText(error),true);},onevent:function(){},onsubtitlechange:function(){},ondrmevent:function(){}});webapis.avplay.prepareAsync(function(){if(!active())return;try{applyVideoLayout(false);webapis.avplay.play();setScreenSaver(false);planeMethodSet=false;applyVideoLayout(false);scheduleRectHold();if(playbackMode==='vod')updateVodBar(0);}catch(e){failed(e,tr('cannotPlay'));}},function(error){failed(error,tr('cannotPrepare'));});}catch(e){failed(e,tr('avFailed'));}}
