function consumeKey(e){if(!e)return;try{e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();}catch(ignoreEvent){}}
function visibleTiles(row){if(!row||row.parentNode.className.indexOf('hidden')>=0)return[];return Array.prototype.slice.call(row.querySelectorAll('.tile.focusable'));}
function homeRows(){var rows=[],search=document.getElementById('searchBtn');if(search)rows.push([search]);var live=visibleTiles(liveRow);if(live.length)rows.push(live);var rec=visibleTiles(recentBox);if(rec.length)rows.push(rec);var cats=visibleTiles(catRow);if(cats.length)rows.push(cats);var catLive=visibleTiles(catLiveRow);if(!catLiveSection.classList.contains('hidden')&&catLive.length)rows.push(catLive);return rows;}
