function findFocus(rows){var r,c,el=document.activeElement;for(r=0;r<rows.length;r++)for(c=0;c<rows[r].length;c++)if(rows[r][c]===el)return{r:r,c:c};return{r:0,c:0};}
function moveGrid(rows,key){if(!rows.length)return;var pos=findFocus(rows),r=pos.r,c=pos.c;if(key===37){if(c>0)c--;}else if(key===39){if(c<rows[r].length-1)c++;}else if(key===38){if(r>0){r--;c=Math.min(c,rows[r].length-1);}}else if(key===40){if(r<rows.length-1){r++;c=Math.min(c,rows[r].length-1);}}rows[r][c].focus();slideFocused(rows[r][c]);}
