function handleBack(e){consumeKey(e);var now=Date.now();if(now-lastBackAt<350)return;lastBackAt=now;if(playing){if(qualityOpen)closeQualityMenu();else leavePlayer(false);return;}if(searchOpen){closeSearch();focusDefault();return;}if(hubOpen){closeHub();return;}if(!catLiveSection.classList.contains('hidden')){catLoadSeq++;catLiveSection.className='shelf hidden';catLiveRow.innerHTML='';activeCategory=null;var homeBody=document.getElementById('homeBody');if(homeBody)homeBody.scrollTop=0;focusRow(catRow,0);return;}try{tizen.application.getCurrentApplication().exit();}catch(x){window.close();}}
