applyLanguage();searchBtn.onclick=function(){openSearch();};watch.onclick=function(){search(input.value,true);};input.addEventListener('input',function(){search(input.value,false);});renderHistory();loadHome();
document.addEventListener('keydown',function(e){remember(e.keyCode);if(e.keyCode===10009||e.keyCode===27){handleBack(e);return;}
  if(playing){showHud();
    if(qualityOpen){if(e.keyCode===38){e.preventDefault();moveQuality(-1);}else if(e.keyCode===40){e.preventDefault();moveQuality(1);}else if(e.keyCode===13){e.preventDefault();applyQuality();}return;}
    if(playbackMode==='vod'&&(e.keyCode===37||e.keyCode===412)){e.preventDefault();startScrub(-1);return;}if(playbackMode==='vod'&&(e.keyCode===39||e.keyCode===417)){e.preventDefault();startScrub(1);return;}
    if(e.keyCode===38){e.preventDefault();if(currentStreamUrl)openQualityMenu();return;}if(e.keyCode===40){e.preventDefault();return;}if(e.keyCode===13){e.preventDefault();toggleChat();return;}
    if(window.webapis&&webapis.avplay){try{var state=webapis.avplay.getState();if(e.keyCode===415&&state!=='PLAYING')webapis.avplay.play();else if(e.keyCode===19&&state==='PLAYING')webapis.avplay.pause();else if(e.keyCode===10252){if(state==='PLAYING')webapis.avplay.pause();else if(state==='PAUSED')webapis.avplay.play();}}catch(ignore){}}return;}
  if(searchOpen){if(document.activeElement===input){if(e.keyCode===39){e.preventDefault();watch.focus();}else if(e.keyCode===40){e.preventDefault();focusFirstResult();}else if(e.keyCode===13){e.preventDefault();search(input.value,true);}return;}if(document.activeElement===watch){if(e.keyCode===37||e.keyCode===38){e.preventDefault();input.focus();}else if(e.keyCode===40){e.preventDefault();focusFirstResult();}else if(e.keyCode===39){e.preventDefault();}else if(e.keyCode===13){e.preventDefault();watch.click();}return;}if(e.keyCode===37||e.keyCode===38||e.keyCode===39||e.keyCode===40){e.preventDefault();moveGrid(searchRows(),e.keyCode);}else if(e.keyCode===13&&document.activeElement)document.activeElement.click();return;}
  if(hubOpen){if(e.keyCode===37||e.keyCode===38||e.keyCode===39||e.keyCode===40){e.preventDefault();moveGrid(hubRows(),e.keyCode);}else if(e.keyCode===13&&document.activeElement)document.activeElement.click();return;}
  if(e.keyCode===37||e.keyCode===38||e.keyCode===39||e.keyCode===40){e.preventDefault();moveGrid(homeRows(),e.keyCode);}else if(e.keyCode===13&&document.activeElement)document.activeElement.click();
},true);
